package com.ptms.repository; import com.ptms.domain.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.util.*; public interface ParkingTicketRepository extends JpaRepository<ParkingTicket,Long>{Optional<ParkingTicket> findByBarcodeIgnoreCase(String b); List<ParkingTicket> findByStatusOrderByDurationHoursAscBarcodeAsc(TicketStatus s); long countByStatus(TicketStatus s); long countByStatusAndDurationHours(TicketStatus s,int h); boolean existsByDurationHoursAndTicketNumber(int h,Integer n); @Query("select max(t.ticketNumber) from ParkingTicket t where t.durationHours=:hours") Integer maxTicketNumber(@Param("hours") int hours);}
